import { Programa } from '../../programas/entities/programa.entity';
import { Locutor } from '../../locutores/entities/locutor.entity';

@Injectable()
export class AsignarLocutorRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Programa) private readonly programas: Repository<Programa>,
    @InjectRepository(Locutor) private readonly locutores: Repository<Locutor>
  ) {}

  buscarProgramaRepository(programaId: number) {
    return this.programas.findOneBy({ id: programaId });
  }

  buscarLocutorRepository(locutorId: number) {
    return this.locutores.findOneBy({ id: locutorId });
  }

  async asignarLocutorRepository(programaId: number, locutorId: number, rol: string) {
    const asignacion = { programaId, locutorId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarLocutorRepository } from './repository';

@Injectable()
export class AsignarLocutorService {
  constructor(private readonly repository: AsignarLocutorRepository) {}

  async asignarLocutorService(programaId: number, locutorId: number, rol: string) {
    const programa = await this.repository.buscarProgramaRepository(programaId);
    const locutor = await this.repository.buscarLocutorRepository(locutorId);
    if (!programa || !locutor) {
      throw new NotFoundException('No existe el programa o el locutor');
    }

    try {
      return await this.repository.asignarLocutorRepository(programaId, locutorId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El locutor ya está asignado a ese programa');
      }
      throw error;
    }
  }
}

